triggered := false
if (all(#MotionSensor).motionSensor_motion ==| true) {
if (triggered == false) {
tmp = all(#LevelControl).light_currentBrightness + 10
        if (tmp > 100) {
tmp = 100
}
all(#LevelControl).light_moveToBrightness(tmp, 0)
        if (all(#LevelControl).light_currentBrightness >= 100) {
break
}
triggered = true
}
}
else {
triggered = false
}

